css:
:host { all: initial; display: block; }
.chz { position: relative; }
.chz-ov { position: absolute; top: 0; left: 0; width: 100%; height: 0; z-index: 9999; color: var(--fg); font-family: var(--body); font-size: 15px; line-height: 1.6; }
.chz { container: chz / inline-size; }

/* 치즈히스토리플러스와 같은 조선일보 글꼴. 블로그에서는 눈누(jsdelivr) 주소로 바꿔 씀 */
/* 레이아웃: 한 해를 52주 눈금으로 깔고, 사건마다 그 위에 보도량 곡선을 그린 세로 목록 */
:host {
  --bg: #f6f7f8; --surface: #ffffff; --fg: #1d232b; --muted: #5d6773; --line: #dde2e7;
  --accent: #2f4f8a; --accent-soft: #e6ecf6; --seal: #b23a2e; --seal-soft: #f8e7e4;
  --c-gp: #2e7d4f; --c-rv: #c0392b; --c-al: #1f62c4; --c-sp: #a8620a; --c-fm: #9d2a5a; --c-cl: #6741c4;
  --display: "ChosunIlboMyungjo", "Noto Serif KR", serif;
  --body: "ChosunGu", "Noto Sans KR", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  --read: "ChosunSm", "Noto Serif KR", serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
}
@media (prefers-color-scheme: dark) { :host([data-theme="auto-dark"]) {
  --bg: #12161b; --surface: #1a2027; --fg: #e5e9ee; --muted: #9aa5b1; --line: #2c343e;
  --accent: #8fb0ea; --accent-soft: #1f2d45; --seal: #f08a7c; --seal-soft: #3a2220; --c-gp: #7fcf9d; --c-rv: #f28b7f; --c-al: #8ab4f8; --c-sp: #f0b450; --c-fm: #f19ac0; --c-cl: #b9a3f5; color-scheme: dark } }
:host([data-theme="dark"]) {
  --bg: #12161b; --surface: #1a2027; --fg: #e5e9ee; --muted: #9aa5b1; --line: #2c343e;
  --accent: #8fb0ea; --accent-soft: #1f2d45; --seal: #f08a7c; --seal-soft: #3a2220; --c-gp: #7fcf9d; --c-rv: #f28b7f; --c-al: #8ab4f8; --c-sp: #f0b450; --c-fm: #f19ac0; --c-cl: #b9a3f5; color-scheme: dark }
.chz { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 15px; line-height: 1.6; }
.wrap { max-width: 880px; margin: 0 auto; padding-block: 28px 64px;
  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }
header { display: grid; gap: 6px; margin-bottom: 18px; }
.eyebrow { font-family: var(--mono); font-size: 12px; letter-spacing: .08em; color: var(--muted); }
h1 { font-family: var(--display); font-size: 28px; line-height: 1.3; margin: 0; text-wrap: balance; }
.lede { color: var(--muted); margin: 0; max-width: 64ch; }
.controls { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; background: var(--bg);
  display: grid; gap: 10px; padding-block: 12px; border-bottom: 1px solid var(--line); }
.chz-off::before { content: ""; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); }
#q { width: 100%; box-sizing: border-box; font: inherit; font-size: 16px; padding: 10px 14px; border: 1px solid var(--line);
  border-radius: 8px; background: var(--surface); color: var(--fg); }
#q:focus-visible, button:focus-visible, summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.chip { font: inherit; font-size: 13px; padding: 4px 11px; border-radius: 999px; border: 1px solid var(--line);
  background: var(--surface); color: var(--fg); cursor: pointer; }
.chip[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: var(--bg); }
.count { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.months { display: grid; grid-template-columns: repeat(12, 1fr); font-family: var(--mono); font-size: 11px; color: var(--muted); }
.list { display: grid; gap: 10px; margin-top: 14px; }
[hidden] { display: none !important; }
a.card { display: grid; gap: 6px; text-decoration: none; color: inherit; }
a.card:hover { border-color: var(--accent); }
.go { font-size: 12.5px; color: var(--accent); margin-left: 6px; white-space: nowrap; }
.back { font: inherit; font-size: 14px; color: var(--accent); background: none; border: 0; padding: 0; cursor: pointer; }
.page { display: grid; gap: 22px; margin-top: 8px; }
.page h2 { margin: 4px 0 0; font-family: var(--serif, inherit); font-size: 26px; line-height: 1.35; }
.page .sec { display: grid; gap: 10px; }
.page .sec > h3 { margin: 0; font-size: 15px; color: var(--muted); font-weight: 600; border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.toc { justify-self: start; min-width: 200px; max-width: 100%; box-sizing: border-box; border: 1px solid var(--line); background: var(--surface); border-radius: 6px; padding: 10px 18px 12px; }
.toc b { font-size: 14px; }
.toc ol { list-style: none; margin: 6px 0 0; padding: 0; display: grid; gap: 3px; }
.toc a { font-size: 14px; color: var(--accent); text-decoration: none; }
.toc a:hover { text-decoration: underline; }
.n { color: var(--accent); font-variant-numeric: tabular-nums; }
a.il { color: var(--accent); text-decoration: none; border-bottom: 1px solid color-mix(in srgb, var(--accent) 35%, transparent); }
a.il:hover { border-bottom-color: var(--accent); }
details.docx { margin: 20px 0 8px; max-width: 680px; border: 1px solid var(--line); border-left: 3px solid var(--seal); border-radius: 10px; background: var(--surface); overflow: hidden; }
details.docx > summary { display: flex; align-items: center; gap: 14px; padding: 13px 16px; cursor: pointer; list-style: none; }
details.docx > summary::-webkit-details-marker { display: none; }
details.docx > summary:hover { background: var(--seal-soft); }
.docx-st { flex: none; font-family: var(--display); font-weight: 700; font-size: 13px; letter-spacing: .12em; color: var(--seal); border: 1.5px solid var(--seal); border-radius: 4px; padding: 3px 5px 3px 7px; transform: rotate(-5deg); }
.docx-tt { display: grid; gap: 2px; min-width: 0; }
.docx-tt b { font-family: var(--display); font-size: 16.5px; line-height: 1.4; word-break: keep-all; }
.docx-tt small { font-size: 12.5px; color: var(--muted); }
.docx-tg { margin-left: auto; flex: none; font-size: 13px; font-weight: 700; color: var(--accent); background: var(--accent-soft); border-radius: 999px; padding: 4px 12px; white-space: nowrap; }
.docx-tg::after { content: '펼쳐 읽기 ▾'; }
details.docx[open] .docx-tg::after { content: '접기 ▴'; }
.docx-b { border-top: 1px dashed var(--line); padding: 20px 24px 6px; background: var(--bg); animation: docx-in .25s ease; }
@keyframes docx-in { from { opacity: 0; transform: translateY(-4px); } }
.docx-b p { font-family: var(--read); font-size: 16.5px; line-height: 1.85; margin: 0 0 .85em; word-break: keep-all; overflow-wrap: break-word; }
.docx-b p.docx-h { font-family: var(--display); font-weight: 700; font-size: 18px; text-align: center; margin-bottom: 1.1em; }
.docx-b p.dn { display: flex; gap: 8px; }
.docx-b p.dn span { flex: none; font-weight: 700; color: var(--seal); }
.docx-b p.docx-sg { text-align: right; font-weight: 700; margin-top: 1.2em; }
.docx-f { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; margin: 14px -24px 0; padding: 10px 24px 14px; border-top: 1px solid var(--line); font-size: 12.5px; color: var(--muted); }
.docx-x { font: inherit; font-weight: 700; color: var(--accent); background: var(--accent-soft); border: 0; border-radius: 999px; padding: 4px 14px; cursor: pointer; }
@container chz (max-width: 520px) { .docx-b { padding: 16px 16px 4px; } .docx-f { margin: 12px -16px 0; padding: 10px 16px 12px; } details.docx > summary { gap: 10px; padding: 12px; } .docx-b p { font-size: 16px; } }
figure.pfig { margin: 18px 0 8px; border: 1px solid var(--line, #ddd); border-radius: 10px; overflow: hidden; background: #f2f1ec; max-width: 680px; }
figure.pfig img { display: block; width: 100%; height: auto; -webkit-user-drag: none; user-select: none; }
figure.pfig figcaption { margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; padding: 10px 14px; font-size: 13.5px; color: #555; background: #f2f1ec; border-top: 1px solid #e3e1da; }
figure.pfig .pf-t { font-weight: 700; color: #222; margin-right: -4px; }
figure.pfig .pf-buy { margin-left: auto; font-weight: 700; color: var(--accent); background: var(--accent-soft); border-radius: 999px; padding: 4px 12px; text-decoration: none; }
.vs { --vs-b: var(--c-sp); --vs-b-soft: color-mix(in srgb, var(--c-sp) 13%, var(--surface)); }
.vs { container-type: inline-size; margin: .6em 0 1.4em; word-break: keep-all; overflow-wrap: break-word; font-family: var(--body); }
.vs-h { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 8px; }
.vs-h b { display: block; padding: 8px 14px; border-radius: 8px; font-size: 15px; }
.vs-h .vs-a { background: var(--accent-soft); color: var(--accent); }
.vs-h .vs-b { background: var(--vs-b-soft); color: var(--vs-b); }
.vs-r { border: 1px solid var(--line); border-radius: 10px; background: var(--surface); margin: 0 0 10px; overflow: hidden; }
.vs-r .vs-k { margin: 0; padding: 9px 14px; font: 700 15.5px var(--body); color: var(--fg); background: var(--bg); border-bottom: 1px solid var(--line); }
.vs-two { display: grid; grid-template-columns: 1fr 1fr; }
.vs-two > div { padding: 12px 14px 13px; border-top: 3px solid var(--accent); }
.vs-two > .vs-b { border-top-color: var(--vs-b); border-left: 1px solid var(--line); }
.vs-two p { margin: 0; font-size: 15.5px; line-height: 1.7; color: var(--fg); }
.vs-who { display: block; margin-top: 6px; font-size: 13px; color: var(--muted); }
.vs-lab { display: none; }
@container (max-width: 640px) {
  .vs-h { display: none; }
  .vs-two { grid-template-columns: 1fr; }
  .vs-two > div { border-top: 0; border-left: 4px solid var(--accent); }
  .vs-two > .vs-b { border-left: 4px solid var(--vs-b); border-top: 1px solid var(--line); }
  .vs-lab { display: block; margin-bottom: 2px; font-size: 12.5px; font-weight: 700; color: var(--accent); }
  .vs-b .vs-lab { color: var(--vs-b); }
}
a.il { word-break: keep-all; }
a.ent { text-decoration: none; color: var(--accent); display: inline-block; }
details.refbox > summary { display: inline-block; font-size: 14px; color: var(--accent); padding: 2px 0; }
details.refbox > summary::before { content: '▸ '; }
details.refbox[open] > summary::before { content: '▾ '; }
details.refbox[open] > summary { margin-bottom: 8px; }
.info { border: 1px solid var(--line); border-radius: 8px; background: var(--surface); overflow: hidden; max-width: 340px; }
.info .ph { aspect-ratio: 4 / 3; display: grid; place-items: center; font-size: 56px; font-weight: 700; color: var(--muted); background: var(--bg); }
.info .phc { font-size: 12px; color: var(--muted); text-align: center; padding: 4px; border-bottom: 1px solid var(--line); }
.info .it { font-weight: 700; text-align: center; padding: 8px; background: var(--accent-soft); }
.info table { width: 100%; border-collapse: collapse; font-size: 14px; }
.info th { width: 78px; text-align: left; vertical-align: top; padding: 8px 10px; color: var(--muted); font-weight: 600; border-top: 1px solid var(--line); background: var(--bg); }
.info td { padding: 8px 10px; border-top: 1px solid var(--line); line-height: 1.5; }
.info ul { margin: 0; padding-left: 16px; }
.plist { display: grid; gap: 8px; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 12px 16px; }
.card .lead { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; line-clamp: 3; overflow: hidden; }
.card .go { display: inline-block; margin: 2px 0 0; }
details.card[open] { border-color: var(--accent); }
summary { list-style: none; cursor: pointer; display: grid; gap: 6px; }
summary::-webkit-details-marker { display: none; }
.top { display: flex; flex-wrap: wrap; gap: 4px 12px; align-items: baseline; }
.when { margin: 2px 0 0; color: var(--muted); font-size: 15px; }
.date { font-family: var(--mono); font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.name { font-weight: 700; font-size: 16.5px; }
.key { font-size: 12px; padding: 1px 8px; border-radius: 4px; background: var(--seal-soft); color: var(--seal); font-weight: 500; }
.stats { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.stats b { color: var(--fg); font-weight: 600; }
svg.spark { width: 100%; height: 40px; display: block; }
.spark .area { fill: var(--accent-soft); }
.spark .lineP { fill: none; stroke: var(--accent); stroke-width: 1.5; }
.spark .ev { stroke: var(--seal); stroke-width: 1.5; stroke-dasharray: 3 2; }
.spark .base { stroke: var(--line); stroke-width: 1; }
.detail { display: grid; gap: 14px; margin-top: 12px; padding-top: 12px; border-top: 1px dashed var(--line); }
.group { display: grid; gap: 6px; }
.label { font-size: 12.5px; color: var(--muted); font-weight: 500; letter-spacing: .02em; }
.ents { display: flex; flex-wrap: wrap; gap: 6px; }
.ent { font: inherit; font-size: 13px; border: 1px solid var(--line); border-radius: 4px; padding: 1px 8px; background: transparent; color: var(--fg); cursor: pointer; }
.ent small { color: var(--muted); font-family: var(--mono); margin-left: 4px; }
.ent:hover { border-color: var(--accent); }
.bars { display: grid; gap: 4px; max-width: 420px; }
.bar { display: grid; grid-template-columns: 70px minmax(0,1fr) 44px; gap: 8px; align-items: center; font-size: 13px; }
.bar i { display: block; height: 8px; border-radius: 2px; background: var(--accent); }
.bar span:last-child { text-align: right; font-family: var(--mono); color: var(--muted); }
.rel { display: flex; flex-wrap: wrap; gap: 6px; }
.rel a, .rel button { text-decoration: none; font: inherit; font-size: 13px; padding: 2px 10px; border-radius: 999px; border: 1px solid var(--accent); background: var(--accent-soft); color: var(--accent); cursor: pointer; }
.note { font-size: 12.5px; color: var(--muted); }
.lead { margin: 0; font-size: 15.5px; line-height: 1.75; max-width: 66ch; }
ol.tl { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; border-left: 2px solid var(--line); }
ol.tl li { display: grid; grid-template-columns: 52px minmax(0,1fr); gap: 10px; padding-left: 12px; position: relative; }
ol.tl li::before { content: ""; position: absolute; left: -6px; top: 8px; width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
ol.tl .d { font-family: var(--mono); font-size: 13px; color: var(--accent); padding-top: 2px; }
ol.tl p { margin: 0; line-height: 1.7; }
.cast li > .ent, .ents .ent { flex: none; white-space: nowrap; }
.cast span { word-break: keep-all; }
ol.tl li.yr { display: block; padding-left: 12px; margin-top: 8px; }
ol.tl li.yr:first-child { margin-top: 0; }
ol.tl li.yr::before { left: -7px; top: 6px; width: 12px; height: 12px; box-shadow: 0 0 0 3px var(--accent-soft); }
ol.tl .y { display: inline-block; font-family: var(--mono); font-weight: 700; font-size: 14px; color: var(--accent); background: var(--accent-soft); padding: 1px 8px; border-radius: 4px; }
ol.tl.long:not(.open) li.more { display: none; }
.tlmore { display: block; width: fit-content; justify-self: start; margin: 14px 0 0 14px; font: inherit; font-size: 14px; color: var(--accent); background: var(--accent-soft); border: 1px solid transparent; border-radius: 999px; padding: 5px 14px; cursor: pointer; }
.tlmore:hover { border-color: var(--accent); }
.cite { display: block; font-size: 12px; color: var(--muted); margin-top: 2px; }
.views { display: grid; gap: 8px; }
.view { display: grid; grid-template-columns: 72px minmax(0,1fr); gap: 10px; }
.view b { font-size: 13.5px; }
.view p { margin: 0; line-height: 1.7; }
.cat { font-size: 12px; padding: 1px 8px; border-radius: 4px; border: 1px solid var(--line); color: var(--muted); }
.body { margin: 0; line-height: 1.8; max-width: 66ch; }
.yd { display: grid; gap: 12px; }
.yd h4 { margin: 0 0 2px; font-size: 14.5px; font-weight: 600; }
.yd p { margin: 0; line-height: 1.75; max-width: 66ch; }
details.card:not([open]) .more { display: inline; }
.more { display: none; font-size: 12.5px; color: var(--accent); margin-left: 6px; }
select { font: inherit; font-size: 13px; padding: 4px 8px; border-radius: 6px; border: 1px solid var(--line); background: var(--surface); color: var(--fg); }
.draft { font-size: 12px; padding: 1px 8px; border-radius: 4px; color: var(--muted); border: 1px dashed var(--line); }
.tog { font-size: 13px; display: inline-flex; gap: 4px; align-items: center; color: var(--fg); }
.hit { margin: 0; font-size: 13.5px; line-height: 1.65; color: var(--muted); border-left: 2px solid var(--accent-soft); padding-left: 10px; }
.hit b { font-weight: 600; color: var(--accent); margin-right: 6px; font-size: 12px; }
.empty { padding: 40px 0; color: var(--muted); text-align: center; }
mark { background: var(--accent-soft); color: inherit; border-radius: 2px; }
.fnl { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.fnl li { line-height: 1.7; }
.fn { font: inherit; font-size: 15px; background: none; border: 0; padding: 0; color: var(--fg); cursor: pointer; text-align: left; text-decoration: underline dotted var(--muted); text-underline-offset: 4px; }
sup.fns { line-height: 0; }
.fnm { font: inherit; font-size: 11px; font-family: var(--mono); line-height: 1; background: none; border: 0; padding: 0 1px; margin-left: 1px; color: var(--accent); cursor: pointer; }
.fnm:hover, .fnm[aria-expanded="true"] { text-decoration: underline; }
.fn sup { color: var(--accent); font-size: 11px; margin-left: 2px; font-family: var(--mono); }
.fn:hover, .fn[aria-expanded="true"] { color: var(--accent); }
.pop { position: absolute; z-index: 20; max-width: min(420px, calc(100vw - 32px)); background: var(--surface); color: var(--fg); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; box-shadow: 0 6px 24px rgba(0,0,0,.14); font-size: 14px; line-height: 1.7; }
.pop h5 { margin: 0 0 4px; font-size: 14px; }
.pop p { margin: 0; }
.pop.pv { pointer-events: none; max-width: min(380px, calc(100vw - 32px)); } .pop .pvd { font-size: 13px; color: var(--muted); margin: 0 0 4px; }
.sheet-bg { position: fixed; inset: 0; background: rgba(0,0,0,.4); z-index: 30; }
.sheet { position: fixed; left: 0; right: 0; bottom: 0; z-index: 31; background: var(--surface); color: var(--fg); border-radius: 14px 14px 0 0; padding: 18px 16px 24px; max-height: 75vh; overflow: auto; font-size: 15px; line-height: 1.75; }
.sheet h5 { margin: 0 0 6px; font-size: 16px; }
.sheet p { margin: 0; }
.sheet .x { float: right; font: inherit; border: 0; background: none; color: var(--muted); font-size: 20px; cursor: pointer; }
a.cite { text-decoration: none; }
a.cite:hover { color: var(--accent); }
ol.refs { margin: 0; padding-left: 22px; display: grid; gap: 4px; font-size: 13.5px; line-height: 1.6; }
ol.refs li { color: var(--muted); padding: 2px 4px; border-radius: 4px; }
ol.refs li b { color: var(--fg); font-weight: 500; }
ol.refs li.on { background: var(--accent-soft); }
footer { margin-top: 28px; font-size: 12.5px; color: var(--muted); max-width: 70ch; }
@container chz (max-width: 520px) { h1 { font-size: 23px; } }
/* 읽기용 크기·폭 */
.chz { font-size: 17px; }
.wrap { max-width: 780px; }
.page h2 { font-family: var(--display); font-size: 32px; }
.lead, .body, .yd p { max-width: none; }
.page .lead { font-family: var(--read); font-size: 19px; line-height: 1.85; }
.body { font-family: var(--read); font-size: 18.5px; line-height: 1.95; }
.body b { font-weight: 700; color: var(--fg); background: linear-gradient(transparent 62%, var(--accent-soft) 62%); }
.page .sec > h3 { font-family: var(--display); font-size: 21px; color: var(--fg); font-weight: 700; padding-bottom: 8px; }
ol.tl p { font-size: 16.5px; line-height: 1.75; }
ol.tl .d { font-size: 14px; }
.cite { font-size: 13.5px; }
.toc b { font-size: 16px; } .toc a { font-size: 16px; } .toc ol { gap: 5px; }
.date { font-size: 14.5px; } .cat, .key { font-size: 13.5px; } .back { font-size: 16px; }
.ent, .rel a, .rel button { font-size: 15px; } .label { font-size: 14px; }
.fnm { font-size: 12.5px; }
.pop { font-size: 15.5px; max-width: min(460px, calc(100vw - 32px)); } .sheet { font-size: 16.5px; }
.fnsrc { font-size: 13.5px !important; }
ol.refs { font-size: 15px; } details.refbox > summary { font-size: 16px; } .note { font-size: 14px; }
.info table { font-size: 15.5px; } .info .it { font-size: 18px; font-family: var(--display); }
.name { font-size: 18px; } .card .lead { font-size: 16.5px; }
