.unv{display:inline-block;font-size:11.5px;color:var(--seal);border:1px solid var(--seal);border-radius:3px;padding:0 4px;margin-left:6px;vertical-align:middle;font-family:var(--body)}.info .gr{color:var(--muted);font-size:13px}

/* ===== 첫 화면 개편 (2020년대 사본) ===== */
.wrap.wide { max-width: 1120px; }
.wrap.wide.isdet { max-width: 880px; }
#top { display: flex; align-items: center; gap: 12px 22px; flex-wrap: wrap; margin-bottom: 18px; }
#top header { display: block; margin: 0; flex: none; }
#top .controls { display: block; min-width: 0; position: static; flex: 1 1 380px; max-width: 640px; background: none; padding: 0; margin: 0; border: 0; }
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--fg); }
.brand .logo { height: 40px; width: auto; }
.brand .wm { display: flex; flex-direction: column; gap: 1px; }
.brand .wm b { font-family: var(--display); font-weight: 900; font-size: 16px; letter-spacing: .12em; line-height: 1.1; }
.brand .wm i { font-style: normal; font-family: var(--display); font-weight: 700; font-size: 11px; letter-spacing: .3em; color: var(--muted); }
#top.home { flex-direction: column; justify-content: center; gap: 26px; margin: clamp(40px, 13vh, 130px) 0 14px; }
#top.home .controls { flex: none; width: 100%; max-width: 660px; }
#top.home .brand { flex-direction: column; gap: 12px; }
#top.home .brand .logo { height: 96px; }
#top.home .brand .wm { align-items: center; gap: 4px; }
#top.home .brand .wm b { font-size: 30px; }
#top.home .brand .wm i { font-size: 14px; }
@media (prefers-color-scheme: dark) { :host([data-theme="auto-dark"]) .brand .logo { background: #f6f7f8; border-radius: 10px; padding: 3px 5px; } }
:host([data-theme="dark"]) .brand .logo { background: #f6f7f8; border-radius: 10px; padding: 3px 5px; }
.sb { position: relative; width: 100%; min-width: 0; display: flex; align-items: center; gap: 10px; box-sizing: border-box; height: 54px; padding: 0 6px; background: var(--surface); border: 1px solid var(--line); border-radius: 999px; }
.sb:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.sb .seg { flex: none; height: 42px; padding: 0 10px 0 16px; border: 0; border-radius: 999px; background: none; color: var(--fg); font: inherit; font-size: 14px; font-weight: 700; display: flex; align-items: center; gap: 6px; cursor: pointer; white-space: nowrap; }
.sb .seg:hover, .sb .seg[aria-expanded="true"], .sb .seg.on { background: var(--accent-soft); color: var(--accent); }
.sb .sep { flex: none; width: 1px; height: 24px; background: var(--line); }
.sb .mag { flex: none; color: var(--muted); }
.sb #q { flex: 1 1 0; min-width: 0; width: auto; height: 42px; padding: 0; border: 0; outline: 0; background: none; font: inherit; font-size: 16px; color: var(--fg); border-radius: 0; }
.sb #q:focus-visible { outline: 0; }
.sb .go2 { flex: none; height: 42px; padding: 0 20px; border: 0; border-radius: 999px; background: var(--accent); color: var(--bg); font: inherit; font-size: 15px; font-weight: 700; cursor: pointer; }
.ac, .yp { position: absolute; left: 0; right: 0; top: calc(100% + 8px); z-index: 20; background: var(--surface); border: 1px solid var(--line); border-radius: 16px; box-shadow: 0 12px 32px rgba(0,0,0,.12); overflow: hidden; }
.ac a { display: flex; align-items: center; gap: 10px; padding: 10px 16px; text-decoration: none; color: var(--fg); font-size: 15px; }
.ac a[aria-selected="true"], .ac a:hover { background: var(--accent-soft); }
.ac .k { flex: none; width: 34px; font-size: 11.5px; color: var(--muted); }
.ac .t { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ac .d { flex: none; font-family: var(--mono); font-size: 12px; color: var(--muted); }
.ac .all { border-top: 1px solid var(--line); color: var(--accent); font-weight: 700; }
.yp { padding: 14px 16px 16px; }
.yp .dec { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
.yp .dec button { font: inherit; font-size: 13.5px; height: 32px; padding: 0 13px; border-radius: 999px; border: 1px solid var(--line); background: none; color: var(--muted); cursor: pointer; }
.yp .dec button[aria-pressed="true"] { background: var(--fg); border-color: var(--fg); color: var(--bg); font-weight: 700; }
.yp .ys { display: grid; grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 8px; }
.yp .ys button { font: inherit; display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 10px 4px; border-radius: 12px; border: 1px solid var(--line); background: none; color: var(--fg); cursor: pointer; }
.yp .ys button:hover, .yp .ys button[aria-pressed="true"] { border-color: var(--accent); background: var(--accent-soft); color: var(--accent); }
.yp .ys b { font-family: var(--display); font-size: 20px; line-height: 1.2; }
.yp .ys small { font-family: var(--mono); font-size: 11.5px; color: var(--muted); }
.yp .clr { margin-top: 12px; font: inherit; font-size: 13.5px; color: var(--accent); background: none; border: 0; padding: 0; cursor: pointer; }
.homehint { text-align: center; font-family: var(--mono); font-size: 12.5px; color: var(--muted); margin: 0; }
/* 연도 화면 */
.yh { display: flex; flex-direction: column; align-items: center; gap: 10px; margin: 6px 0 4px; }
.yh .nav { display: flex; align-items: baseline; gap: 18px; }
.yh .nav button { font: inherit; font-family: var(--display); font-weight: 700; font-size: 17px; color: var(--muted); background: none; border: 0; padding: 6px 2px; cursor: pointer; }
.yh .nav button:hover { color: var(--accent); }
.yh h2 { margin: 0; font-family: var(--display); font-weight: 900; font-size: 44px; line-height: 1; }
.yh h2 small { font-size: 26px; }
.yh .cnt { margin: 0; font-family: var(--mono); font-size: 13px; color: var(--muted); }
.ybar { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 10px 16px; }
.vt { display: flex; gap: 2px; padding: 3px; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); }
.vt button { font: inherit; font-size: 13.5px; height: 34px; padding: 0 14px; border-radius: 999px; border: 0; background: none; color: var(--muted); display: flex; align-items: center; gap: 7px; cursor: pointer; }
.vt button[aria-pressed="true"] { background: var(--fg); color: var(--bg); font-weight: 700; }
.fc { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.fc button { font: inherit; font-size: 13.5px; height: 32px; padding: 0 13px; border-radius: 999px; border: 1px solid var(--line); background: var(--surface); color: var(--fg); cursor: pointer; white-space: nowrap; }
.fc button small { font-family: var(--mono); font-size: 11.5px; opacity: .7; }
.fc button[aria-pressed="true"] { background: var(--fg); border-color: var(--fg); color: var(--bg); font-weight: 700; }
.zl { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 28px minmax(0, 1fr); grid-auto-rows: 19px; margin-top: 8px; }
.zl::before { content: ""; position: absolute; left: 50%; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--line); }
.zm { grid-column: 1 / -1; justify-self: center; align-self: center; position: relative; margin: 0; height: 22px; line-height: 22px; padding: 0 13px; border-radius: 999px; background: var(--fg); color: var(--bg); font-family: var(--display); font-weight: 700; font-size: 13px; }
.zd { grid-column: 2; justify-self: center; align-self: center; position: relative; width: 10px; height: 10px; border-radius: 50%; box-sizing: border-box; background: var(--surface); border: 2px solid var(--muted); }
.zd.core { background: var(--seal); border-color: var(--seal); }
.ze { align-self: center; position: relative; display: flex; align-items: center; gap: 10px; min-width: 0; max-width: 100%; text-decoration: none; color: var(--fg); font-size: 14.5px; line-height: 1.3; }
.ze.L { grid-column: 1; justify-self: end; padding-right: 20px; }
.ze.R { grid-column: 3; justify-self: start; padding-left: 20px; }
.ze::after { content: ""; position: absolute; top: 50%; width: 14px; height: 1px; background: var(--line); }
.ze.L::after { right: 0; } .ze.R::after { left: 0; }
.ze.core::after { background: var(--seal); }
.ze .t { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ze.core .t { font-family: var(--display); font-weight: 700; font-size: 18px; }
.ze .d { flex: none; font-family: var(--mono); font-size: 12.5px; color: var(--muted); }
.ze.core .d { color: var(--seal); }
.ze:hover .t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.mg { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 26px 32px; align-items: start; margin-top: 14px; }
.mg section { border-top: 2px solid var(--fg); padding-top: 8px; }
.mg h3 { margin: 0 0 6px; display: flex; align-items: baseline; font-family: var(--display); font-weight: 900; font-size: 24px; line-height: 1.2; }
.mg h3 span { font-size: 14px; font-weight: 700; margin: 0 auto 0 2px; }
.mg h3 small { font-family: var(--mono); font-weight: 400; font-size: 12px; color: var(--muted); }
.mg a { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 8px; align-items: baseline; padding: 4px 0; text-decoration: none; color: var(--fg); font-size: 14.5px; line-height: 1.4; }
.mg a .d { font-family: var(--mono); font-size: 12.5px; text-align: right; color: var(--muted); }
.mg a.core .d { color: var(--seal); } .mg a.core .t { font-weight: 700; }
.mg a:hover .t { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.mg .none { margin: 4px 0; font-size: 13px; color: var(--muted); }
.ynote { margin: 18px 0 0; font-size: 13px; color: var(--muted); text-align: center; }
/* 검색 결과 */
.sh { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 14px; margin: 4px 0 2px; }
.sh h2 { margin: 0; font-size: 19px; font-family: var(--body); font-weight: 700; }
.sh .cnt { font-family: var(--mono); font-size: 13px; color: var(--muted); }
.sh + .fc { justify-content: flex-start; margin: 10px 0 14px; }
.sgrid { display: grid; grid-template-columns: minmax(0, 1fr) 232px; gap: 28px; align-items: start; }
.sgrid .main { display: grid; gap: 10px; min-width: 0; }
.sy { display: flex; align-items: baseline; gap: 10px; margin: 14px 0 0; padding-bottom: 6px; border-bottom: 2px solid var(--fg); font-family: var(--display); font-weight: 900; font-size: 24px; line-height: 1.2; }
.sy small { font-family: var(--mono); font-weight: 400; font-size: 12.5px; color: var(--muted); }
.sgrp { display: grid; gap: 10px; }
.sgrp:not(.open) > .card.more { display: none; }
.smore { justify-self: start; font: inherit; font-size: 14px; font-weight: 700; color: var(--accent); background: none; border: 0; padding: 4px 0; cursor: pointer; }
.side { position: sticky; top: 16px; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; }
.side h3 { margin: 0 0 8px; font-size: 13px; color: var(--muted); font-weight: 700; }
.side button { font: inherit; width: 100%; display: grid; grid-template-columns: 44px minmax(0, 1fr) 26px; gap: 8px; align-items: center; padding: 6px 0; border: 0; background: none; color: var(--fg); cursor: pointer; font-family: var(--mono); font-size: 13px; text-align: left; }
.side button i { display: block; height: 6px; border-radius: 3px; background: var(--line); overflow: hidden; }
.side button i b { display: block; height: 100%; border-radius: 3px; background: var(--accent); opacity: .55; }
.side button span:last-child { text-align: right; color: var(--muted); }
.side button:hover i b, .side button[aria-pressed="true"] i b { opacity: 1; }
.side button[aria-pressed="true"] { font-weight: 700; color: var(--accent); }
.side .clr { display: block; width: auto; margin-top: 6px; font-family: var(--body); color: var(--accent); }
@media (max-width: 860px) { .sgrid { grid-template-columns: minmax(0, 1fr); } .side { position: static; order: -1; } }
@media (max-width: 720px) {
  .zl { grid-template-columns: 22px minmax(0, 1fr); grid-auto-rows: auto; row-gap: 2px; }
  .zl::before { left: 11px; }
  .zm { grid-column: 1 / -1 !important; grid-row: auto !important; justify-self: start; margin: 12px 0 4px; }
  .zd { grid-column: 1 !important; grid-row: auto !important; }
  .ze.L, .ze.R { grid-column: 2 !important; grid-row: auto !important; justify-self: start; padding: 6px 0 6px 6px; }
  .ze .d { order: -1; min-width: 40px; }
  .ze::after { display: none; }
  .ze .t { white-space: normal; }
  .yh h2 { font-size: 36px; }
  .sb .go2 { padding: 0 14px; }
  .sb .seg { padding: 0 6px 0 12px; }
}
/* ===== 상세 화면: 머리 부분 + 오른쪽 정보 상자와 목차 + 앞뒤 사건 ===== */
.wrap.wide.isdet.evd { max-width: 1120px; }
.page.dr { gap: 12px; }
.page.dr .navb { font-size: 14px; }
.dhero { display: grid; gap: 12px; padding: 10px 0 24px; border-bottom: 2px solid var(--fg); }
.dhero .top { margin: 0; align-items: center; gap: 8px; }
.dhero .top .cat, .dhero .top .key { font-size: 13px; padding: 3px 11px; border-radius: 999px; }
.page.event .dhero h2 { margin: 0; font-family: var(--display); font-weight: 900; font-size: clamp(30px, 4.3vw, 46px); line-height: 1.2; letter-spacing: -.01em; text-wrap: balance; }
.dhero .when { margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 16px; font-size: 15px; color: var(--muted); }
.dhero .when a { color: var(--accent); text-decoration: none; font-weight: 600; font-size: 14px; }
.dhero .when a:hover { text-decoration: underline; text-underline-offset: 3px; }
.dgrid { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 0 52px; align-items: start; }
.dmain { display: grid; gap: 22px; min-width: 0; padding-top: 24px; }
.dside { align-self: stretch; min-width: 0; padding-top: 24px; display: flex; flex-direction: column; gap: 20px; }
.ibox { border: 1px solid var(--line); background: var(--surface); border-radius: 10px; overflow: hidden; }
.ibox h3 { margin: 0; padding: 9px 16px; font-size: 13px; font-weight: 700; letter-spacing: .06em; background: var(--fg); color: var(--bg); }
.ibox dl { margin: 0; padding: 4px 16px 8px; display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 0 12px; font-size: 14.5px; line-height: 1.55; }
.ibox dt { color: var(--muted); font-size: 13px; padding: 9px 0; border-top: 1px solid var(--line); }
.ibox dd { margin: 0; padding: 9px 0; border-top: 1px solid var(--line); min-width: 0; overflow-wrap: anywhere; }
.ibox dt:first-of-type, .ibox dt:first-of-type + dd { border-top: 0; }
.ibox dd a { color: var(--accent); text-decoration: none; font-weight: 600; }
.ibox dd a:hover { text-decoration: underline; text-underline-offset: 3px; }
.ibox dd .r { display: block; color: var(--muted); font-size: 12.5px; line-height: 1.45; }
.ibox dd div + div { margin-top: 6px; }
.ibox dd.src { font-family: var(--mono); font-size: 12.5px; color: var(--muted); }
.pn { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 10px; padding-top: 22px; border-top: 1px solid var(--line); }
.pn a { display: grid; gap: 5px; padding: 14px 16px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); text-decoration: none; color: var(--fg); min-width: 0; }
.pn a.n { grid-column: 2; text-align: right; }
.pn small { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.pn b { font-family: var(--display); font-size: 16.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pn a:hover { border-color: var(--accent); } .pn a:hover b { color: var(--accent); }
@media (min-width: 901px) {
  .dstick { position: sticky; top: 18px; max-height: calc(100vh - 36px); overflow: auto; display: grid; gap: 22px; }
  .dside .toc { justify-self: stretch; min-width: 0; border: 0; border-left: 2px solid var(--line); border-radius: 0; background: none; padding: 2px 0 2px 16px; }
  .dside .toc b { font-size: 13px; letter-spacing: .06em; color: var(--muted); }
  .dside .toc ol { gap: 1px; margin-top: 8px; }
  .dside .toc a { display: block; padding: 3px 0; font-size: 14.5px; line-height: 1.45; color: var(--fg); }
  .dside .toc ol ol { padding-left: 1.1em; margin: 0; }
  .dside .toc ol ol a { font-size: 13.5px; color: var(--muted); }
  .dside .toc .n { font-family: var(--mono); font-size: 12px; color: var(--muted); }
  .dside .toc a.cur { color: var(--accent); font-weight: 700; }
  .dside .toc.fold:not(.open) > ol { max-height: none; -webkit-mask-image: none; mask-image: none; }
  .dside .toc .tocx { display: none; }
}
@media (max-width: 900px) {
  .dgrid { grid-template-columns: minmax(0, 1fr); }
  .dstick { display: contents; }
  .cwslot.rail { display: none; }
  .dside { order: -1; padding-top: 18px; gap: 14px; }
  .dmain { padding-top: 20px; }
  .dhero { padding-bottom: 18px; }
  .ibox .dup { display: none; }
  .ibox dt:not(.dup), .ibox dd:not(.dup) { border-top: 1px solid var(--line); }
  .ibox .dup + dd.dup + dt, .ibox .dup + dd.dup + dt + dd { border-top: 0; }
}
@media (max-width: 520px) { .pn { grid-template-columns: minmax(0, 1fr); } .pn a.n { grid-column: 1; } }
/* ===== 홍보 배너 자리 (크몽 연표 · POD 책) ===== */
.cwpromo { display: grid; gap: 5px; margin: 14px 0 18px; min-width: 0; }
.cwpromo .sl { font-size: 11px; letter-spacing: .1em; color: var(--muted); }
.cwpromo .pb { display: block; border-radius: 8px; overflow: hidden; }
.cwpromo .pb img { display: block; width: 100%; height: auto; aspect-ratio: 4 / 1; object-fit: cover; }
.cwpromo .pb.demo { display: grid; place-content: center; gap: 4px; text-align: center; aspect-ratio: 4 / 1; padding: 12px; border: 1px dashed var(--accent); background: var(--accent-soft); color: var(--fg); }
.cwpromo .pb.demo.pod { border-color: var(--muted); background: var(--surface); }
.cwpromo .pb.demo b { font-size: 16px; font-weight: 700; word-break: keep-all; }
.cwpromo .pb.demo small { font-family: var(--mono); font-size: 12px; color: var(--muted); }
.cwpromo .pb.demo em { font-style: normal; font-size: 12px; color: var(--muted); }
.dmain > .cwpromo { margin: 26px 0 8px; }
.yh + .cwpromo { width: 100%; max-width: 880px; margin-inline: auto; }
@media (max-width: 720px) { .cwpromo .pb.demo, .cwpromo .pb.m img { aspect-ratio: 2 / 1; } }
/* ===== 광고 자리 ===== */
.cwslot { display: grid; gap: 5px; margin: 8px 0; min-width: 0; }
.cwslot .sl { font-size: 11px; letter-spacing: .1em; color: var(--muted); text-align: center; }
.cwslot .sb2 { display: grid; place-content: center; gap: 3px; text-align: center; min-height: 120px; border: 1px dashed var(--muted); border-radius: 8px; color: var(--muted); background: repeating-linear-gradient(135deg, transparent 0 11px, var(--line) 11px 12px); }
.cwslot .sb2 b { font-size: 14px; font-weight: 700; }
.cwslot .sb2 small { font-family: var(--mono); font-size: 12px; }
.cwslot.on { min-height: 120px; }
.cwslot.rail { margin: 0; }
.cwslot.rail .sb2 { height: 250px; min-height: 0; }
.cwslot.rail.on { min-height: 250px; }
.zl + .cwslot { margin: 22px 0; }
.ynote + .cwslot { margin-top: 26px; }
.sgrid .main > .cwslot { margin: 18px 0 4px; }
@media (max-width: 720px) { .cwslot .sb2 { min-height: 250px; } .cwslot.on { min-height: 250px; } }
/* ===== 모바일 손질 ===== */
.page h2, .page .sec > h3, .page h4, .ze .t, .mg .t, .card .name, .pn b, .sh h2, .ac .t { word-break: keep-all; overflow-wrap: anywhere; }
.ibox dd .more { color: var(--muted); font-size: 12.5px; }
@media (max-width: 900px) {
  /* 상세: 제목 → 개요 → 사건 정보 → 목차 → 나머지 순서로 */
  .dgrid { row-gap: 22px; padding-top: 20px; }
  .dmain { display: contents; }
  .dmain > * { order: 2; }
  .dmain > .sec:first-child { order: 0; }
  .dgrid > .dside { order: 1; padding-top: 0; }
  .ibox dd div { display: inline; margin: 0; }
  .ibox dd div + div::before { content: " · "; color: var(--muted); }
  .ibox dd .r { display: none; }
  .toc a { display: block; padding: 5px 0; }
  .toc ol { gap: 0; }
}
@media (max-width: 860px) {
  /* 검색 결과: 연도로 좁히기를 옆으로 미는 한 줄로 */
  .side { display: flex; gap: 8px; align-items: center; overflow-x: auto; padding: 0 0 4px; border: 0; background: none; border-radius: 0; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
  .side::-webkit-scrollbar { display: none; }
  .side h3 { display: none; }
